    fn probe_tree() {
        let language: tree_sitter::Language = LANGUAGE.into();
        let mut parser = tree_sitter::Parser::new();
        parser.set_language(&language).unwrap();
        let src = "use /lib\n\n// a comment here\nscope ApplicationScope:\n    pitch:\n        What the application is for, in a sentence\n        or two with {a.b} and \\ escaped {x} \\ here: there.\n\n        - not an item\n    items:\n        - one two\n        + more\n    code:\n        ```rust\n        let x = 1;\n        ```\n    raw:\n        \\\\\\\n        kept as is\n        \\\\\\\n    name: value goes here\n";
